const { join } = require('path')
const { readProject } = require('../../projectReader')
const { merge } = require('../../merge')
const { srv4, html5RepoHost, html5Runtime, xsuaa, appDeployer, approuter, mtxSidecar4 } = require('../../registries/mta')
const { srvApi, html5RepoApi } = require('../../registries/xs-app')
const { exists, read } = require('../../../cds').utils

module.exports = class Html5RepoTemplate extends require('../../plugin') {

    requires() {
        const { hasKyma } = readProject()
        if (hasKyma) return ['destination']
    }

    static help() {
        return 'SAP BTP HTML5 Application Repository'
    }

    static hasInProduction(env) {
        return !!env.requires['html5-repo'] || !!env.requires['html5-runtime'] || !!env.requires['html5-host']
    }

    async run() {
        const project = readProject()
        const { apps, appPath, configFile } = project
        await merge(__dirname, 'files/package.json.hbs').into(configFile, { project })

        // Fiori/UI5 apps deploy a manifest.json; static apps (plain index.html) don't
        await Promise.all(apps.filter(a => !a.isStatic).map(({ app }) =>
            merge(__dirname, 'files/manifest.json')
                .into(join(appPath, app, 'webapp/manifest.json'), { project })
        ))
    }

    async combine(facet) {
        const project = readProject(facet)
        const {
            isJava, srv, appPath, apps,
            hasApprouter, hasMta, addMta, hasKyma, hasXsuaa, hasMultitenancy, hasUI5,
            addSample, addApprouter, addKyma, addMultitenancy, addWorkzoneStandard, addXsuaa, addIas
        } = project

        await Promise.all(apps.map(async ({ app }) => {
            project.app = app
            project.hasIndexHtml = exists(join(appPath, app, 'webapp/index.html'))
            const additions = [srvApi, html5RepoApi]
            await merge(__dirname, 'files/xs-app.json.hbs').into(join(appPath, app, 'xs-app.json'), { with: project, additions })
            const pJsonPath = join(appPath, app, 'package.json')
            const pJson = exists(pJsonPath) ? await read(pJsonPath) : {}
            project.ui5 = hasUI5 || pJson.devDependencies?.['@ui5/cli']
            await merge(__dirname, 'files/app-package.json.hbs').into(pJsonPath, { project })
        }))

        for (const { app } of apps) {
            project.app = app
            const pJsonPath = join(appPath, app, 'package.json')
            const pJson = exists(pJsonPath) ? await read(pJsonPath) : {}
            const ui5 = hasUI5 || pJson.devDependencies?.['@ui5/cli']
            if (ui5) {
                const isTs = project.isTypescript || !!pJson.devDependencies?.typescript || !!pJson.dependencies?.typescript
                const additions = [{ in: 'builder.customTasks', where: { name: 'ui5-task-zipper' } }]
                if (isTs) additions.unshift({ in: 'builder.customTasks', where: { name: 'ui5-tooling-transpile-task' }, at: 0 })
                project.isTypescript = isTs
                await merge(__dirname, 'files/ui5.yaml.hbs').into(join(appPath, app, 'ui5.yaml'), { project, additions })
            }
        }

        if (addMultitenancy) {
            await merge({ cds: { requires: { 'html5-repo': true } } }).into('mtx/sidecar/package.json')
        }

        const affected = addXsuaa || addApprouter || addWorkzoneStandard || addMultitenancy || addSample || addIas
        if (addMta || affected && hasMta) {
            const srvModule = srv4(srv.path)
            project.apps = apps
            const hasApps = apps.length > 0
            const relationships = []
            if (hasApps) {
                relationships.push({
                    insert: [html5RepoHost, 'name'],
                    into: [appDeployer, 'requires', 'name'],
                })
            }
            const appModules = []
            for (const { app } of project.apps) {
                const html5App = { in: 'modules', where: { type: 'html5', path: `${appPath}${app}` } }
                relationships.push({
                    insert: [html5App],
                    into: [appDeployer, 'build-parameters.requires'],
                })
            }
            if (hasApprouter) {
                relationships.push({
                    insert: [html5Runtime, 'name'],
                    into: [approuter, 'requires', 'name'],
                })
            }
            if (hasMultitenancy) {
                relationships.push({
                    insert: [html5Runtime, 'name'],
                    into: [isJava ? srvModule : mtxSidecar4('gen/mtx/sidecar'), 'requires', 'name']
                })
                relationships.push({
                    insert: [html5RepoHost, 'name'],
                    into: [isJava ? srvModule : mtxSidecar4('gen/mtx/sidecar'), 'requires', 'name']
                })
            }
            if (hasXsuaa && hasApps) {
                relationships.push({
                    insert: [xsuaa, 'name'],
                    into: [appDeployer, 'requires']
                })
            }
            await merge(__dirname, 'files/mta.yaml.hbs').into('mta.yaml', {
                with: project,
                additions: [srvModule, ...(hasApps ? [appDeployer] : []), html5RepoHost, ...appModules],
                relationships
            })
        }

        if (addKyma) {
            const additions = [{
                in: 'modules',
                where: { name: `${project.appName}-html5-deployer` }
            }]
            await merge(__dirname, '/files/containerize.yaml.hbs').into('containerize.yaml', { with: project, additions })
        }

        if (addKyma || affected && hasKyma) {
            await merge(__dirname, 'files/values.yaml.hbs').into('chart/values.yaml', { with: project })
        }
    }
}
